            case CF_OPERATION("ECC_PrivateToPublic"):
                executorECC_PrivateToPublic.Run(ds, payload.data(), payload.size());
                break;
            case CF_OPERATION("ECC_ValidatePubkey"):
                executorECC_ValidatePubkey.Run(ds, payload.data(), payload.size());
